using System;
using System.Linq;
using UnityEditor;
using UnityEngine;

namespace UnityBox.AnimatorOptimizer.ComponentMigration
{
    /// <summary>The plugin's explicit project-wide component-reference upgrade action.</summary>
    public static class ComponentReferenceUpgrade
    {
        [MenuItem("Tools/UnityBox/Animator Optimizer/Upgrade Component References")]
        public static void RunMenu()
        {
            try
            {
                Execute(() => EditorUtility.DisplayDialog("AO — Upgrade Component References",
                    "扫描整个 Assets，识别并升级 Animator Optimizer 的旧组件引用。写入前备份原文件及 metadata。\n\n"
                    + "相关的已保存且无修改的 Scene / Prefab 编辑上下文会临时关闭并恢复；未保存的编辑及其依赖会保留并跳过。"
                    + "不保存用户修改，不删除或合并重复组件。\n\n"
                    + "Scan all Assets and upgrade this plugin's recognized legacy component references. Original files and metadata are backed up. "
                    + "Affected saved, clean editing contexts are reopened; unsaved edits and their dependencies are preserved and skipped.",
                    "Upgrade / 升级", "Cancel / 取消"));
            }
            catch (Exception exception) { Debug.LogException(exception); }
        }

        // A single confirmation precedes discovery and all project I/O.
        public static MigrationResult Execute(Func<bool> confirmation)
        {
            if (confirmation == null) throw new ArgumentNullException(nameof(confirmation));
            if (!confirmation()) return null;
            try
            {
                EditorUtility.DisplayProgressBar("AO Component References", "Scanning Assets and upgrading component references…", 0.1f);
                var result = MigrationEngine.UpgradeProjectAssets();
                string summary = "AO component references: " + result.RepairedComponents + " repaired in "
                    + result.ChangedAssets.Count + " assets."
                    + (result.BackupDirectory.Length > 0 ? " Backup and report: " + result.BackupDirectory : "");
                if (result.Issues.Count > 0)
                    summary += "\n" + string.Join("\n", result.Issues.GroupBy(issue => issue.AssetPath + ": " + issue.Message)
                        .Select(group => group.Key));
                Debug.Log(summary);
                return result;
            }
            finally { EditorUtility.ClearProgressBar(); }
        }
    }
}
